-- будує модель GolemCave у шаблоні ніші: валуни/мох (Plastic + Studs, як карта), темний прохід (SmoothPlastic, без studs),
-- ліхтарі (Neon + PointLight), жовте коло (копія кола Sell), напис CAVE, ProximityPrompt (Style Custom — свій інтерфейс)
local n = workspace.NichePrefabs.NichePrefab_Stage1
local old = n:FindFirstChild("GolemCave"); if old then old:Destroy() end
local base = CFrame.new(-787, 1.2, 357) * CFrame.Angles(0, math.rad(134), 0)
local m = Instance.new("Model"); m.Name = "GolemCave"
local body = Instance.new("Model"); body.Name = "Body"; body.Parent = m
for i, r in ipairs(D) do
	if r[2] <= 0.05 or r[3] <= 0.05 or r[4] <= 0.05 then continue end
	local p = Instance.new(r[1] == 'b' and "Part" or r[1] == 'w' and "WedgePart" or "CornerWedgePart")
	p.Size = Vector3.new(r[2], r[3], r[4])
	p.CFrame = base * CFrame.new(r[5], r[6], r[7], r[8], r[9], r[10], r[11], r[12], r[13], r[14], r[15], r[16])
	p.Color = Color3.fromHex(r[17]); p.Anchored = true
	p.TopSurface = Enum.SurfaceType.Smooth; p.BottomSurface = Enum.SurfaceType.Smooth
	local tag = r[18]
	if tag == "dark" then
		p.Material = Enum.Material.SmoothPlastic; p.CanCollide = true; p.CastShadow = false; p.Name = "Dark"
	elseif tag == "lamp" then
		p.Material = Enum.Material.Neon; p.CanCollide = false; p.Name = "Lamp"
		local l = Instance.new("PointLight"); l.Color = Color3.fromHex("ffc860"); l.Range = 12; l.Brightness = 1.2; l.Shadows = false; l.Parent = p
	else
		p.Material = Enum.Material.Plastic; p.MaterialVariant = "Studs"; p.Name = "Rock"
		p.CanCollide = tag ~= "prop" or r[2] > 0.8
	end
	p.Parent = body
end
-- коло (як у Sell): копія, менша, жовта
local sellRing = n.Sell.Ring
local ring = sellRing:Clone(); ring.Name = "Ring"
for _, d in ring:GetDescendants() do if d:IsA("BillboardGui") then d:Destroy() end end
local rc = ring:FindFirstChild("RingCenter")
ring.PrimaryPart = rc
ring:PivotTo(base * CFrame.new(0, 0.216, 9.6))
ring:ScaleTo(0.62)
local YEL = Color3.fromHex("ffd21e")
for _, d in ring:GetDescendants() do
	if d:IsA("BasePart") and d.Name == "RingSeg" then d.Color = YEL
	elseif d:IsA("BasePart") and d.Name == "RingGlow" then d.Color = Color3.fromHex("ffcc2a")
	elseif d:IsA("ParticleEmitter") then d.Color = ColorSequence.new(Color3.fromHex("ffe27a")) end
end
ring.Parent = m
-- напис CAVE над колом (як SELL: Montserrat Heavy, градієнт, темний контур) — золотий
local sa = ring:FindFirstChild("SignAnchor") or Instance.new("Part")
sa.Name = "SignAnchor"; sa.Anchored = true; sa.CanCollide = false; sa.CanQuery = false; sa.CanTouch = false; sa.Transparency = 1
sa.Size = Vector3.new(0.9, 0.9, 0.9); sa.CFrame = rc.CFrame + Vector3.new(0, 11.5, 0); sa.Parent = ring
